<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/bootstrap.php';
$rawId = $_GET['id'] ?? null;
$id = is_string($rawId) ? filter_var($rawId, FILTER_VALIDATE_INT, ['options'=>['min_range'=>1]]) : false;
if (!$id) abort_request(404, 'Dieses Angebot wurde nicht gefunden.');
$item = market_find($pdo, (int)$id, true);
if ($item === null) abort_request(404, 'Dieses Angebot ist nicht verfügbar.');
$isAuction = $item['type'] === 'auction';
if ($isAuction && empty($forceAuction)) redirect('/marketplace/view-auction.php?id=' . (int)$id);
if (!$isAuction && !empty($forceAuction)) redirect('/marketplace/view-item.php?id=' . (int)$id);
$user = current_user($pdo);
$isOwner = $user && (int)$user['id'] === (int)$item['seller_id'];
$hasEnded = $item['status'] !== 'active' || ($isAuction && $item['ends_at'] !== null && strtotime($item['ends_at'] . ' UTC') <= time());
$price = $isAuction && $item['current_bid_cents'] !== null ? (int)$item['current_bid_cents'] : (int)$item['price_cents'];
$canContact = !$isOwner && (!$hasEnded || ($user && (int)($item['highest_bidder_id'] ?? 0) === (int)$user['id']));
$imageCount = max(1, min(5, (int)($item['image_count'] ?? 0)));
$history = $isAuction ? market_public_bid_history($pdo, (int)$id, 20) : [];
$pageTitle = $item['title'];
$pageDescription = substr($item['description'], 0, 160);
include __DIR__ . '/../includes/header.php';
?>
<main class="page-width page detail-page"><nav class="breadcrumbs" aria-label="Brotkrumennavigation"><a href="/marketplace/index.php">Entdecken</a><?= ui_icon('chevron') ?><a href="/marketplace/search.php?category_id=<?= (int)$item['category_id'] ?>"><?= h($item['category_name']) ?></a><?= ui_icon('chevron') ?><span><?= $isAuction ? 'Auktion' : 'Festpreisangebot' ?></span></nav>
<div class="listing-layout"><div><section class="listing-gallery reveal" aria-label="Produktbilder" data-gallery><div class="gallery-main"><img src="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=0&amp;size=large" width="1000" height="800" alt="<?= h($item['title']) ?> – Ansicht 1" data-gallery-main fetchpriority="high"></div><?php if ($imageCount > 1): ?><div class="gallery-thumbs"><?php for ($position=0; $position<$imageCount; $position++): ?><a href="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=<?= $position ?>&amp;size=large" data-gallery-src="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=<?= $position ?>&amp;size=large" data-gallery-alt="<?= h($item['title']) ?> – Ansicht <?= $position+1 ?>" <?= $position === 0 ? 'aria-current="true"' : '' ?>><img src="/marketplace/image.php?id=<?= (int)$id ?>&amp;position=<?= $position ?>&amp;size=thumb" alt="Ansicht <?= $position+1 ?> anzeigen" width="100" height="100" loading="lazy"></a><?php endfor; ?></div><?php endif; ?></section><section class="listing-story"><h2>Die Geschichte zum Stück.</h2><div class="listing-description"><?= h($item['description']) ?></div></section>
<?php if ($isAuction): ?><section class="bid-history"><h2>Öffentlicher Gebotsverlauf</h2><?php if ($history === []): ?><p class="muted">Noch keine Gebote. Private Maximalgebote erscheinen hier nicht.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Ereignis</th><th>Betrag</th><th>Zeitpunkt (UTC)</th></tr></thead><tbody><?php foreach ($history as $event): ?><tr><td><?= h(['bid'=>'Gebot','buyout'=>'Sofortkauf','close'=>'Abschluss','close_no_bid'=>'Ohne Gebot beendet'][$event['event_type']] ?? 'Ereignis') ?></td><td><?= $event['amount_cents'] === null ? '–' : h(money_eur((int)$event['amount_cents'])) ?></td><td><?= h($event['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="help">Angezeigt werden veröffentlichte Preise. Hinterlegte Maximalgebote bleiben privat.</p><?php endif; ?></section><?php endif; ?>
</div><aside class="listing-information reveal"><span class="badge <?= $isAuction ? 'accent' : 'muted' ?>"><?= $isAuction ? 'Auktion' : 'Festpreis' ?></span><h1><?= h($item['title']) ?></h1><div class="detail-location"><?= ui_icon('pin') ?><?= h($item['zip'] . ' ' . $item['city']) ?></div><div class="detail-price"><?= h(money_eur($price)) ?></div><p class="detail-price-label"><?= $isAuction ? ($item['current_bid_cents'] === null ? 'Startpreis' : 'Aktuelles Höchstgebot') : 'Angebotspreis' ?></p>
<?php if ($hasEnded): ?><div class="notice"><?= $item['status'] === 'active' ? 'Die Gebotsfrist ist abgelaufen. Der serverseitige Abschluss wird verarbeitet.' : ($item['status'] === 'sold' ? 'Dieses Angebot wurde als verkauft markiert.' : 'Diese Auktion ist beendet.') ?></div><?php endif; ?>
<?php if ($isAuction && !$hasEnded): ?><section class="auction-panel panel"><div class="auction-time"><?= ui_icon('clock') ?><span>Verbleibende Gebotszeit</span></div><div class="countdown" data-countdown="<?= h(str_replace(' ', 'T', $item['ends_at']) . 'Z') ?>"><?= h($item['ends_at']) ?> UTC</div><?php if ($isOwner): ?><p class="help">Du kannst auf dein eigenes Angebot nicht bieten.</p><?php elseif ($user): ?><?php if ((int)($item['highest_bidder_id'] ?? 0) === (int)$user['id']): ?><p class="notice success">Du hältst das führende Gebot.</p><?php endif; ?><form action="/actions/place-bid.php" method="post"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$id ?>"><label class="field">Dein privates Maximalgebot (€)<input name="max_bid" inputmode="decimal" maxlength="14" required placeholder="Zum Beispiel 50,00" autocomplete="off"></label><button class="button" type="submit">Gebot abgeben <?= ui_icon('arrow') ?></button></form><p class="help">Das System bietet nur so weit wie nötig. Ein gültiges Gebot in den letzten zwei Minuten verlängert die Frist auf mindestens zwei Minuten.</p><?php else: ?><a class="button" href="/auth/login.php">Zum Bieten anmelden <?= ui_icon('arrow') ?></a><?php endif; ?></section><?php endif; ?>
<div class="detail-actions"><?php if ($isOwner && !$hasEnded): ?><a class="button" href="/user/edit-listing.php?id=<?= (int)$id ?>">Inserat bearbeiten <?= ui_icon('arrow') ?></a><?php elseif ($canContact): ?><a class="button <?= $isAuction ? 'secondary' : '' ?>" href="<?= $user ? '/user/chat.php?listing_id=' . (int)$id . '&user_id=' . (int)$item['seller_id'] : '/auth/login.php' ?>">Verkäufer kontaktieren <?= ui_icon('arrow') ?></a><?php endif; ?>
<?php if ($user && !$isOwner && !$hasEnded): ?><form method="post" action="/user/toggle-watchlist.php"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$id ?>"><button class="button secondary" type="submit"><?= ui_icon('heart') ?>Merkliste ändern</button></form><?php endif; ?>
<?php if ($isAuction && !$hasEnded && !$isOwner && (int)($item['buyout_cents'] ?? 0) > 0 && $item['current_bid_cents'] === null): ?><form method="post" action="/marketplace/buyout-request.php?id=<?= (int)$id ?>"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$id ?>"><button class="button secondary" type="submit">Sofort kaufen · <?= h(money_eur((int)$item['buyout_cents'])) ?></button></form><?php endif; ?>
<?php if ($isAuction && $item['status'] === 'ended' && $user && !empty($item['highest_bidder_id']) && ($isOwner || (int)$item['highest_bidder_id'] === (int)$user['id'])): ?><a class="button secondary" href="/user/rate-user.php?listing_id=<?= (int)$id ?>">Transaktionspartner bewerten <?= ui_icon('arrow') ?></a><?php endif; ?></div>
<dl class="detail-facts"><div><dt>Zustand</dt><dd><?= h($item['condition_label']) ?></dd></div><div><dt>Übergabe</dt><dd><?= $item['pickup'] ? 'Abholung' : '' ?><?= $item['pickup'] && $item['shipping'] ? ' / ' : '' ?><?= $item['shipping'] ? 'Versand' : '' ?></dd></div><div><dt>Kategorie</dt><dd><?= h($item['category_name']) ?></dd></div><div><dt>Angebotsnummer</dt><dd>#<?= (int)$id ?></dd></div></dl>
<a class="seller-summary" href="/marketplace/profile.php?user_id=<?= (int)$item['seller_id'] ?>"><span class="seller-avatar"><?= ui_icon('account') ?></span><div><strong><?= h($item['seller_username']) ?></strong><p>Verkäuferprofil ansehen ↗</p></div></a><p class="help sale-note">Kaufpreis und Übergabe vereinbaren Käufer und Verkäufer miteinander. Eine Zahlung oder Treuhand ist hier nicht enthalten.</p></aside></div></main>
<?php include __DIR__ . '/../includes/footer.php'; ?>
